import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const r="/assets/websocket-und-http.CaBAqOJg.svg",p=JSON.parse('{"title":"Wie der Adapter Verbindung und Status behandelt","description":"","frontmatter":{"order":1,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/05.hintergrund/01.verbindung-und-aktualisierung.md"},"headers":[],"relativePath":"de/adapter/wled/hintergrund/verbindung-und-aktualisierung.md","filePath":"de/adapter/wled/hintergrund/verbindung-und-aktualisierung.md","lastUpdated":null}'),s={name:"de/adapter/wled/hintergrund/verbindung-und-aktualisierung.md"};function d(l,e,o,h,c,u){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="wie-der-adapter-verbindung-und-status-behandelt" tabindex="-1">Wie der Adapter Verbindung und Status behandelt <a class="header-anchor" href="#wie-der-adapter-verbindung-und-status-behandelt" aria-label="Permalink to &quot;Wie der Adapter Verbindung und Status behandelt&quot;">​</a></h1><p><a id="states-only-updated-after-30"></a></p><h2 id="warum-werden-zustande-erst-nach-30-sekunden-aktualisiert-gibt-es-push-statt-polling" tabindex="-1">Warum werden Zustände erst nach 30 Sekunden aktualisiert, gibt es Push statt Polling? <a class="header-anchor" href="#warum-werden-zustande-erst-nach-30-sekunden-aktualisiert-gibt-es-push-statt-polling" aria-label="Permalink to &quot;Warum werden Zustände erst nach 30 Sekunden aktualisiert, gibt es Push statt Polling?&quot;">​</a></h2><p><strong>Kurz:</strong> Ja, seit v0.6.0 kommen Änderungen per Push. Der Adapter hält zu jedem Gerät mit WLED 0.12 oder neuer eine WebSocket-Verbindung, und WLED schickt jede Änderung sofort. Die 30 Sekunden sind das Polling-Intervall. Es zählt für die Daten nur, wenn keine WebSocket-Verbindung besteht, also bei älterer Firmware oder nach einem Verbindungsabbruch. Dann fragt der Adapter das Gerät im Takt des Intervalls per HTTP ab.</p><h3 id="so-halt-der-adapter-die-werte-aktuell" tabindex="-1">So hält der Adapter die Werte aktuell <a class="header-anchor" href="#so-halt-der-adapter-die-werte-aktuell" aria-label="Permalink to &quot;So hält der Adapter die Werte aktuell&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Verbindung</th><th>Wann</th><th>Neue Werte von WLED</th><th>Prüfung im Takt des Intervalls</th></tr></thead><tbody><tr><td>WebSocket</td><td>WLED 0.12 oder neuer, Normalfall</td><td>sofort, sobald sich am Gerät etwas ändert</td><td>ein <code>ping</code>, auf das innerhalb eines Intervalls ein <code>pong</code> kommen muss</td></tr><tr><td>HTTP</td><td>WLED älter als 0.12, oder der WebSocket ist gerade getrennt</td><td>erst bei der nächsten Abfrage, also nach bis zu einem Intervall</td><td>eine vollständige Abfrage von <code>http://192.168.x.y/json</code></td></tr></tbody></table><p>Befehle aus ioBroker schickt der Adapter in beiden Fällen sofort ab, über den WebSocket, wenn er verbunden ist, sonst per HTTP.</p><p>WLED schickt bei jeder Änderung den ganzen Zustand mit den Geräte-Informationen. Werte unter <code>_info</code> wie <code>_info.wifi.rssi</code>, <code>_info.uptime</code> oder <code>_info.freeheap</code> ändern sich deshalb bei WebSocket nur, wenn sich am Gerät etwas ändert, nicht in einem festen Takt.</p><p><img src="'+r+`" alt="Zwei Wege: Mit WebSocket schickt WLED jede Änderung sofort, der Adapter sendet nur im Takt des Intervalls ein ping und erwartet ein pong. Ohne WebSocket fragt der Adapter das Gerät im Takt des Intervalls per HTTP ab, Änderungen kommen bis zu ein Intervall später an."></p><h3 id="woran-du-erkennst-welche-verbindung-lauft" tabindex="-1">Woran du erkennst, welche Verbindung läuft <a class="header-anchor" href="#woran-du-erkennst-welche-verbindung-lauft" aria-label="Permalink to &quot;Woran du erkennst, welche Verbindung läuft&quot;">​</a></h3><ul><li>Beim Verbinden steht <code>&lt;Gerät&gt; connected</code> als Info im Log. Das ist der WebSocket.</li><li>Kann das Gerät keinen WebSocket, steht als Warnung <code>Client 192.168.x.y does not support websocket, please consider upgrading your WLED firmware to &gt;= 0.12. Switching to http-APi !</code> im Log.</li><li><code>wled.&lt;Instanz&gt;.&lt;MAC&gt;._info.ws</code> zeigt, wie viele WebSocket-Verbindungen das Gerät gerade hat. Steht dort <code>-1</code>, kann die Firmware keinen WebSocket.</li></ul><h3 id="wenn-anderungen-trotzdem-spat-ankommen" tabindex="-1">Wenn Änderungen trotzdem spät ankommen <a class="header-anchor" href="#wenn-anderungen-trotzdem-spat-ankommen" aria-label="Permalink to &quot;Wenn Änderungen trotzdem spät ankommen&quot;">​</a></h3><ol><li>Prüfe, ob das Gerät per WebSocket verbunden ist, siehe oben.</li><li>Aktualisiere WLED auf 0.12 oder neuer, wenn noch eine ältere Firmware läuft.</li><li>Ist das Gerät oft kurz offline, fällt es zwischendurch auf HTTP zurück. Siehe <a href="./../fehlerbehebung/verbindung-und-start#wled-devices-show-red-offline">Warum zeigen alle WLED rot oder offline?</a></li><li>Brauchst du bei HTTP schnellere Werte, verkleinere das „Intervall in Sekunden“ in den Instanzeinstellungen.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Bis v0.5.x hatte der Adapter keinen WebSocket und fragte alle Geräte im Takt des Intervalls ab. Beiträge, nach denen sich Werte nur alle 30 Sekunden ändern, stammen oft aus dieser Zeit.</p></div><p><strong>Ab v0.10.0:</strong> Werte von Usermods, etwa Sensoren, ändern sich ohne Änderung am Zustand, deshalb schickt WLED sie nicht per WebSocket. Der Adapter fragt sie bei Geräten mit Usermods zusätzlich im Takt des Intervalls ab (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/929" target="_blank" rel="noreferrer">#929</a>).</p><p><strong>Siehe auch:</strong> <a href="./../referenz/instanz-einstellungen#polling-interval-auto-discovery">Wo stelle ich Polling-Intervall und Auto-Erkennung ein?</a> · <a href="#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a> · <a href="./werte-und-integrationen#states-only-written-they-change">Werden States nur bei Änderung geschrieben?</a></p><p><a id="tell-whether-device-really-online"></a></p><h2 id="woran-sehe-ich-ob-ein-gerat-wirklich-online-ist-info-connection-online" tabindex="-1">Woran sehe ich, ob ein Gerät wirklich online ist (info.connection, _online)? <a class="header-anchor" href="#woran-sehe-ich-ob-ein-gerat-wirklich-online-ist-info-connection-online" aria-label="Permalink to &quot;Woran sehe ich, ob ein Gerät wirklich online ist (info.connection, _online)?&quot;">​</a></h2><p><strong>Kurz:</strong> Ob ein Gerät erreichbar ist, zeigt <code>wled.&lt;Instanz&gt;.&lt;MAC&gt;._info._online</code>. <code>wled.&lt;Instanz&gt;.info.connection</code> sagt nur, dass die Instanz läuft und bereit ist, nicht, ob ein Gerät antwortet. Beide Werte laufen der Wirklichkeit etwas hinterher, weil der Adapter ein Gerät nur im Takt des Polling-Intervalls prüft.</p><h3 id="die-beiden-datenpunkte" tabindex="-1">Die beiden Datenpunkte <a class="header-anchor" href="#die-beiden-datenpunkte" aria-label="Permalink to &quot;Die beiden Datenpunkte&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Gilt für</th><th><code>true</code> heißt</th><th><code>false</code> heißt</th></tr></thead><tbody><tr><td><code>wled.&lt;Instanz&gt;.info.connection</code></td><td>die Instanz</td><td>Der Adapter ist gestartet, hat die bekannten Geräte angefragt und die Bonjour-Suche gestartet. Das gilt auch, wenn kein einziges Gerät geantwortet hat.</td><td>Die Instanz ist gestoppt.</td></tr><tr><td><code>wled.&lt;Instanz&gt;.&lt;MAC&gt;._info._online</code></td><td>ein Gerät</td><td>Das Gerät hat bei der letzten Prüfung geantwortet.</td><td>Das Gerät hat nicht geantwortet, oder die Instanz ist gestoppt oder startet gerade.</td></tr></tbody></table><p><code>_info._online</code> ist im Geräteobjekt als Online-Status hinterlegt. Der Admin zeigt ihn deshalb im Reiter „Objekte“ und im „Konfig-Manager“ (in älteren Admin-Versionen „Geräte“) beim Gerät an. In der Gerätetabelle der Instanzeinstellungen steht ein Gerät mit <code>true</code> auf grün, mit <code>false</code> auf rot.</p><h3 id="wie-schnell-der-wert-umspringt" tabindex="-1">Wie schnell der Wert umspringt <a class="header-anchor" href="#wie-schnell-der-wert-umspringt" aria-label="Permalink to &quot;Wie schnell der Wert umspringt&quot;">​</a></h3><ul><li><strong>Gerät geht aus:</strong> Mit WebSocket merkt der Adapter es, wenn auf sein nächstes <code>ping</code> innerhalb eines Intervalls kein <code>pong</code> kommt. Mit den voreingestellten 30 Sekunden steht <code>_info._online</code> deshalb erst nach bis zu einer Minute auf <code>false</code>. Ohne WebSocket springt der Wert bei der nächsten HTTP-Abfrage um, die keine Antwort bekommt.</li><li><strong>Gerät kommt wieder:</strong> Der Adapter merkt es bei der nächsten Prüfung. Nach mehreren Fehlversuchen kann das bis zu einer Stunde dauern, siehe <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen?</a></li><li><strong>Instanz startet:</strong> Beim Start setzt der Adapter <code>_info._online</code> aller Geräte auf <code>false</code> und dann bei jedem Gerät, das antwortet, wieder auf <code>true</code>.</li></ul><p>In einem Skript reagierst du auf <code>_info._online</code>, zum Beispiel für eine Meldung, wenn ein Gerät ausfällt:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;._info._online&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, change: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ne&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">obj</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (obj.state.val </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;WLED &lt;Gerät&gt; ist nicht erreichbar&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><h3 id="grenzen-bis-v0-9-2" tabindex="-1">Grenzen bis v0.9.2 <a class="header-anchor" href="#grenzen-bis-v0-9-2" aria-label="Permalink to &quot;Grenzen bis v0.9.2&quot;">​</a></h3><p><strong>Bis v0.9.2:</strong> Die Erkennung hat mehrere Lücken:</p><ul><li>Schließt WLED die WebSocket-Verbindung selbst, etwa bei einem Neustart, wertet der Adapter das nicht aus. Er merkt den Ausfall erst beim nächsten fehlenden <code>pong</code>.</li><li>Der vorgesehene Ablauf, nach dem <code>_info._online</code> nach zwei Intervallen ohne Antwort von selbst <code>false</code> wird, greift nie.</li><li>Geräte, die erst nach dem Start dazukamen, prüft der Adapter gar nicht. Ihr <code>_info._online</code> bleibt nach einem Ausfall stehen.</li><li>Bei einem Gerät, das beim Start nicht erreichbar ist, schreibt der Adapter <code>_info._online</code> als Text statt als Wahrheitswert. Der Admin zeigt das Gerät dann als online an, obwohl es aus ist.</li></ul><p><strong>Ab v0.9.3:</strong> Alle vier Lücken sind geschlossen. Schließt WLED die Verbindung, steht <code>_info._online</code> sofort auf <code>false</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>). Antwortet ein Gerät zwei Intervalle lang nicht, wird <code>_info._online</code> von selbst <code>false</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/900" target="_blank" rel="noreferrer">#900</a>). Auch später gefundene Geräte werden geprüft (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). <code>_info._online</code> ist immer ein Wahrheitswert (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>).</p><p><strong>Ab v0.10.0:</strong> Die Geräteliste in den Instanzeinstellungen zeigt „Online“ oder „Offline“ und oben die Zahl, zum Beispiel „2 von 3 Geräten online“. Sie lädt den Status alle 10 Sekunden neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/verbindung-und-start#wled-shown-offline-after-restart">Warum wird WLED nach Neustart oder Update als offline angezeigt?</a> · <a href="#become-false-device-goes-offline">Warum wird on false, wenn das Gerät offline geht?</a></p><p><a id="become-false-device-goes-offline"></a></p><h2 id="warum-wird-on-false-wenn-das-gerat-offline-geht-und-was-passiert-beim-adapterstart" tabindex="-1">Warum wird on false, wenn das Gerät offline geht, und was passiert beim Adapterstart? <a class="header-anchor" href="#warum-wird-on-false-wenn-das-gerat-offline-geht-und-was-passiert-beim-adapterstart" aria-label="Permalink to &quot;Warum wird on false, wenn das Gerät offline geht, und was passiert beim Adapterstart?&quot;">​</a></h2><p><strong>Kurz:</strong> In v0.9.2 setzt der Adapter beim Start der Instanz <code>on</code> auf <code>false</code> und <code>bri</code> auf <code>0</code>, für alle Geräte, bis sich das Gerät meldet. Geht ein Gerät im laufenden Betrieb offline, behalten <code>on</code> und <code>bri</code> dagegen ihren letzten Wert. Skripte, die auf <code>on</code> oder <code>bri</code> reagieren, lösen deshalb bei jedem Neustart der Instanz aus. Ab v0.9.3 setzt der Adapter <code>on</code> und <code>bri</code> gar nicht mehr zurück.</p><h3 id="was-in-v0-9-2-passiert" tabindex="-1">Was in v0.9.2 passiert <a class="header-anchor" href="#was-in-v0-9-2-passiert" aria-label="Permalink to &quot;Was in v0.9.2 passiert&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ereignis</th><th><code>on</code></th><th><code>bri</code></th><th><code>_info._online</code></th></tr></thead><tbody><tr><td>Start der Instanz</td><td>wird <code>false</code></td><td>wird <code>0</code></td><td>wird <code>false</code></td></tr><tr><td>Gerät meldet sich nach dem Start</td><td>echter Wert vom Gerät</td><td>echter Wert vom Gerät</td><td>wird <code>true</code></td></tr><tr><td>Gerät geht im laufenden Betrieb offline</td><td>bleibt beim letzten Wert</td><td>bleibt beim letzten Wert</td><td>wird <code>false</code>, sobald der Adapter den Ausfall bemerkt</td></tr></tbody></table><p>Seit v0.7.2 war vorgesehen, <code>on</code> und <code>bri</code> auch beim Trennen der Verbindung zurückzusetzen. Der Teil des Codes, der das tun sollte, läuft in v0.9.2 aber nie, weil eine Bedingung davor nie erfüllt ist.</p><p>Die Werte beim Start sind keine Befehle. Der Adapter schreibt sie als bestätigte Werte (<code>ack=true</code>), an das Gerät geht nichts. Ein Licht, das an war, bleibt an.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Ein Skript, das auf eine Änderung von <code>on</code> oder <code>bri</code> reagiert, löst in v0.9.2 bei jedem Neustart der Instanz bis zu zweimal aus: einmal beim Zurücksetzen auf <code>false</code> und <code>0</code>, einmal, wenn das Gerät seinen echten Wert meldet. Prüf im Skript deshalb, ob das Gerät online ist, bevor du etwas tust.</p></div><h3 id="so-schutzt-du-dein-skript" tabindex="-1">So schützt du dein Skript <a class="header-anchor" href="#so-schutzt-du-dein-skript" aria-label="Permalink to &quot;So schützt du dein Skript&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;.on&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, change: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ne&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">obj</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Beim Neustart der Instanz ist das Gerät noch nicht online</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;MAC&gt;._info._online&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).val) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`WLED &lt;Gerät&gt; ist jetzt \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">obj</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">state</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">val</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;an&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;aus&#39;}\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Willst du wissen, ob ein Gerät erreichbar ist, nimm <code>_info._online</code> und nicht <code>on</code>. Ein Gerät, das offline ist, zeigt in <code>on</code> nur den letzten bekannten Wert.</p><p><strong>Ab v0.9.3:</strong> <code>on</code> und <code>bri</code> behalten beim Offline-Gehen und beim Start der Instanz ihren letzten Wert. Meldet sich das Gerät wieder, liest der Adapter die echten Werte ein (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>). Skripte lösen beim Neustart nur noch aus, wenn sich am Gerät wirklich etwas geändert hat. <code>_info._online</code> wird beim Start weiterhin <code>false</code> und dann wieder <code>true</code>.</p><p><strong>Siehe auch:</strong> <a href="#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a> · <a href="./../anleitungen/skripte#tell-whether-wled-was-switched">Woran erkenne ich, ob WLED per Telegram, VIS oder Web-Oberfläche geschaltet wurde?</a></p>`,45)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
